```systemverilog
`timescale 1ns/1ps

module frame_arb_mux_tb;

  localparam int S_COUNT = 4;
  localparam int DATA_WIDTH = 32;
  localparam int USER_WIDTH = 1;
  localparam int KEEP_WIDTH = DATA_WIDTH / 8;

  // DUT signals
  logic clk;
  logic rst;
  logic [S_COUNT-1:0][DATA_WIDTH-1:0] s_tdata;
  logic [S_COUNT-1:0][KEEP_WIDTH-1:0] s_tkeep;
  logic [S_COUNT-1:0] s_tvalid;
  logic [S_COUNT-1:0] s_tready;
  logic [S_COUNT-1:0] s_tlast;
  logic [S_COUNT-1:0][USER_WIDTH-1:0] s_tuser;
  logic [DATA_WIDTH-1:0] m_tdata;
  logic [KEEP_WIDTH-1:0] m_tkeep;
  logic m_tvalid;
  logic m_tready;
  logic m_tlast;
  logic [USER_WIDTH-1:0] m_tuser;

  frame_arb_mux #(
    .S_COUNT(S_COUNT),
    .DATA_WIDTH(DATA_WIDTH),
    .USER_WIDTH(USER_WIDTH)
  ) dut (
    .clk_i(clk),
    .rst_i(rst),
    .s_tdata_i(s_tdata),
    .s_tkeep_i(s_tkeep),
    .s_tvalid_i(s_tvalid),
    .s_tready_o(s_tready),
    .s_tlast_i(s_tlast),
    .s_tuser_i(s_tuser),
    .m_tdata_o(m_tdata),
    .m_tkeep_o(m_tkeep),
    .m_tvalid_o(m_tvalid),
    .m_tready_i(m_tready),
    .m_tlast_o(m_tlast),
    .m_tuser_o(m_tuser)
  );

  // Clock
  initial begin clk = 1'b0; forever #5 clk = ~clk; end

  // Reset
  initial rst = 1'b1;

  task automatic bfm_reset(input int cycles = 4);
    @(negedge clk);
    rst = 1'b1;
    repeat (cycles) @(posedge clk);
    @(negedge clk);
    rst = 1'b0;
  endtask

  task automatic bfm_send(input int k,
                          input logic [DATA_WIDTH-1:0] data,
                          input logic [KEEP_WIDTH-1:0] keep,
                          input logic last,
                          input logic [USER_WIDTH-1:0] user);
    @(negedge clk);
    s_tdata[k] = data;
    s_tkeep[k] = keep;
    s_tlast[k] = last;
    s_tuser[k] = user;
    s_tvalid[k] = 1'b1;
    forever begin
      @(posedge clk);
      if (s_tready[k]) break;
    end
  endtask

  task automatic bfm_idle(input int k);
    @(negedge clk);
    s_tvalid[k] = 1'b0;
  endtask

  task automatic bfm_ready(input logic value);
    @(negedge clk);
    m_tready = value;
  endtask

  // Watchdog
  initial begin
    #20_000_000;
    $display("RESULT: FAIL (watchdog)");
    $finish;
  end

  // Beat tracking
  typedef struct {
    int input_id;
    int frame_seq;
    int beat_in_frame;
    bit is_last;
    logic [KEEP_WIDTH-1:0] keep;
    logic [USER_WIDTH-1:0] user;
  } beat_info_t;

  beat_info_t beat_map[int];
  int global_beat_ctr;
  int frame_ctr[S_COUNT];
  int beat_ctr[S_COUNT];

  int frames_committed;
  int frames_delivered;

  int errors;

  // Output frame tracking
  int out_current_input;
  int out_current_frame;
  int out_current_beat;
  bit out_in_frame;

  // Fairness tracking
  int out_frame_inputs[$];

  // Output monitor
  always @(posedge clk) begin
    if (rst) begin
      out_in_frame = 0;
      out_current_input = -1;
      out_current_frame = -1;
      out_current_beat = -1;
    end else if (m_tvalid && m_tready) begin
      automatic logic [DATA_WIDTH-1:0] data = m_tdata;
      automatic int key = data;
      automatic beat_info_t info;
      automatic int in_id;
      automatic int i;
      automatic bit seen[4];

      if (!beat_map.exists(key)) begin
        $display("FAIL: S12/S4 unknown tdata %h at time %0t", data, $time);
        errors++;
      end else begin
        info = beat_map[key];
        in_id = info.input_id;

        // S4: payload integrity
        if (m_tkeep !== info.keep) begin
          $display("FAIL: S4 tkeep mismatch at time %0t (exp %h got %h)", $time, info.keep, m_tkeep);
          errors++;
        end
        if (m_tuser !== info.user) begin
          $display("FAIL: S4 tuser mismatch at time %0t", $time);
          errors++;
        end
        if (m_tlast !== info.is_last) begin
          $display("FAIL: S4 tlast mismatch at time %0t", $time);
          errors++;
        end

        // S3: frame atomicity
        if (out_in_frame) begin
          if (in_id != out_current_input) begin
            $display("FAIL: S3 frame interleaved at time %0t", $time);
            errors++;
          end
          if (info.frame_seq != out_current_frame) begin
            $display("FAIL: S3 frame changed mid-frame at time %0t", $time);
            errors++;
          end
          if (info.beat_in_frame != out_current_beat + 1) begin
            $display("FAIL: S4 beat out of order at time %0t", $time);
            errors++;
          end
        end else begin
          if (info.beat_in_frame != 0) begin
            $display("FAIL: S4 frame started mid-frame at time %0t", $time);
            errors++;
          end
          out_current_input = in_id;
          out_current_frame = info.frame_seq;
        end

        out_current_beat = info.beat_in_frame;

        if (info.is_last) begin
          out_in_frame = 0;
          frames_delivered++;

          // Fairness check
          out_frame_inputs.push_back(in_id);
          if (out_frame_inputs.size() > 16) out_frame_inputs.pop_front();
          if (out_frame_inputs.size() == 16) begin
            for (i = 0; i < 4; i++) seen[i] = 0;
            for (i = 0; i < 16; i++) seen[out_frame_inputs[i]] = 1;
            for (i = 0; i < 4; i++) begin
              if (!seen[i]) begin
                $display("FAIL: S10 fairness violated (input %0d missing) at time %0t", i, $time);
                errors++;
              end
            end
          end
        end else begin
          out_in_frame = 1;
        end
      end
    end
  end

  // Send a frame on input k
  task automatic send_frame(input int k, input int num_beats);
    int fs;
    int b;
    bit is_last;
    logic [DATA_WIDTH-1:0] data;
    logic [KEEP_WIDTH-1:0] keep;
    logic [USER_WIDTH-1:0] user;

    fs = frame_ctr[k];
    frame_ctr[k]++;

    for (b = 0; b < num_beats; b++) begin
      is_last = (b == num_beats - 1);
      data = global_beat_ctr;
      keep = $urandom;
      user = $urandom;

      beat_map[data] = '{input_id: k, frame_seq: fs, beat_in_frame: b, is_last: is_last, keep: keep, user: user};

      global_beat_ctr++;
      beat_ctr[k]++;

      bfm_send(k, data, keep, is_last, user);

      if (is_last) frames_committed++;
    end
  endtask

  // Wait for all committed frames to be delivered
  task automatic wait_all_delivered();
    int timeout;
    timeout = 0;
    while (frames_delivered < frames_committed && timeout < 100000) begin
      @(posedge clk);
      timeout++;
    end
    if (frames_delivered < frames_committed) begin
      $display("FAIL: S5 timeout waiting for delivery (%0d/%0d)", frames_delivered, frames_committed);
      errors++;
    end
  endtask

  // Main test
  initial begin
    int k;
    int i;

    errors = 0;
    global_beat_ctr = 0;
    frames_committed = 0;
    frames_delivered = 0;
    out_in_frame = 0;
    out_current_input = -1;
    out_current_frame = -1;
    out_current_beat = -1;

    for (k = 0; k < S_COUNT; k++) begin
      s_tvalid[k] = 0;
      s_tdata[k] = 0;
      s_tkeep[k] = 0;
      s_tlast[k] = 0;
      s_tuser[k] = 0;
      frame_ctr[k] = 0;
      beat_ctr[k] = 0;
    end
    m_tready = 0;

    bfm_reset();

    // Phase 1: Basic test - one frame per input
    $display("[TB] Phase 1: Basic test");
    fork
      begin
        for (k = 0; k < S_COUNT; k++) send_frame(k, 3);
      end
    join
    wait_all_delivered();

    // Phase 2: Backpressure test
    $display("[TB] Phase 2: Backpressure test");
    fork
      begin
        for (i = 0; i < 200; i++) begin
          bfm_ready($urandom % 2);
        end
        bfm_ready(1);
      end
      begin
        for (k = 0; k < S_COUNT; k++) begin
          send_frame(k, 1);
          send_frame(k, 2);
          send_frame(k, 4);
        end
      end
    join
    wait_all_delivered();

    // Phase 3: Fairness test
    $display("[TB] Phase 3: Fairness test");
    bfm_ready(1);
    fork
      begin
        for (k = 0; k < S_COUNT; k++) begin
          for (i = 0; i < 20; i++) send_frame(k, 1);
        end
      end
    join
    wait_all_delivered();

    // Phase 4: Reset test
    $display("[TB] Phase 4: Reset test");
    // Hold output, send a frame (gets buffered)
    bfm_ready(0);
    fork
      begin
        send_frame(0, 3);
      end
    join
    // Now assert reset
    bfm_reset();
    // Reset counters
    frames_committed = 0;
    frames_delivered = 0;
    beat_map.delete();
    out_in_frame = 0;
    out_current_input = -1;
    out_current_frame = -1;
    out_current_beat = -1;
    // Release output
    bfm_ready(1);
    // Wait a few cycles, check m_tvalid is low
    repeat (10) @(posedge clk);
    if (m_tvalid) begin
      $display("FAIL: S12 m_tvalid high after reset");
      errors++;
    end
    // Send new frame
    fork
      begin
        send_frame(1, 2);
      end
    join
    wait_all_delivered();

